import { createElement as h, useEffect } from "react";
import { createRoot } from "react-dom/client";
import { ReactFlow, useEdgesState, useNodesState } from "@xyflow/react";

const services = [
  { id: "client", position: { x: 30, y: 130 }, data: { label: "Client" } },
  { id: "cache", position: { x: 240, y: 130 }, data: { label: "Cache" } },
  { id: "db", position: { x: 450, y: 60 }, data: { label: "Database" } },
  { id: "replica", position: { x: 450, y: 210 }, data: { label: "Read replica" } },
].map((node) => ({ ...node, sourcePosition: "right", targetPosition: "left" }));

// The scenario names the hops the request takes.
const hops = (path) =>
  path.slice(1).map((to, i) => ({ id: path[i] + "-" + to, source: path[i], target: to, animated: true }));

const dim = (path) => (node) => ({ ...node, style: path.includes(node.id) ? undefined : { opacity: 0.35 } });

document.body.style.cssText = "height:100%;font:13px system-ui";
const root = document.createElement("div");
root.style.cssText = "height:100%";
document.body.append(root);
const bounds = [[0, 0], [root.clientWidth, root.clientHeight]];

function Read() {
  const [nodes, setNodes, onNodesChange] = useNodesState(services);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // Positions survive a new scenario; only the path changes.
  useEffect(
    () =>
      wb.onScenario(({ data: { path } }) => {
        setNodes((current) => current.map(dim(path)));
        setEdges(hops(path));
      }),
    [],
  );

  return h(ReactFlow, {
    nodes,
    edges,
    onNodesChange,
    onEdgesChange,
    nodeExtent: bounds,
    translateExtent: bounds,
    minZoom: 1,
    maxZoom: 1,
    proOptions: { hideAttribution: true },
  });
}

createRoot(root).render(h(Read));
